```ts
import { AuthenticationClient, AuthApiError } from 'auth0';
const auth0 = new AuthenticationClient({ domain, clientId, clientSecret });
try {
  const resp = await auth0.oauth.passwordGrant({ username, password });
  return resp.data.access_token;
} catch (e) {
  if (e instanceof AuthApiError && e.error === 'mfa_required') startMfa(e);
  throw e;
}
